WITH base AS (SELECT * FROM employees WHERE NOT is_remote AND (job_title <> 'Analyst' OR salary >= 57000)), summary AS (SELECT is_remote, MAX(hire_date) AS latest_hire_date, ROUND((100 * SUM(CASE WHEN job_title = 'Analyst' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_analyst FROM base GROUP BY is_remote) SELECT is_remote, latest_hire_date, pct_analyst FROM summary WHERE pct_analyst < 54 ORDER BY latest_hire_date;
